CREATE COLUMN TABLE "TEST_AP"."OARG" ("CstGrpCode" SMALLINT CS_INT NOT NULL , "CstGrpName" NVARCHAR(20) NOT NULL , "GroupNum" NVARCHAR(20), "Custom" DECIMAL(21,6) CS_FIXED, "BuyTax" DECIMAL(21,6) CS_FIXED, "OtherTax" DECIMAL(21,6) CS_FIXED, "TotalTax" DECIMAL(21,6) CS_FIXED, "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "cstAllcAcc" NVARCHAR(15), "cstExpAcc" NVARCHAR(15), "PortAddr" NVARCHAR(50), "PortState" NVARCHAR(3), "ExciExpAcc" NVARCHAR(15), "ExciAlcAcc" NVARCHAR(15), PRIMARY KEY ("CstGrpCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OARG_GROUP_NAME" ON "TEST_AP"."OARG" ( "CstGrpName" ASC )